import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Baq27OmJ.js";var i=JSON.parse(`{"title":"Overview","description":"","frontmatter":{"title":"Overview"},"headers":[],"relativePath":"guides/the-manual/testing/index.md","filePath":"guides/the-manual/testing/index.md"}`),a={name:`guides/the-manual/testing/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="testing-with-holodeck" tabindex="-1">Testing with Holodeck <a class="header-anchor" href="#testing-with-holodeck" aria-label="Permalink to “Testing with Holodeck”">​</a></h1><p><a href="https://github.com/warp-drive-data/warp-drive/tree/main/packages/holodeck" target="_blank" rel="noreferrer"><code>@warp-drive/holodeck</code></a> is the HTTP mock server <strong><em>Warp</em>Drive</strong> uses for its own test suites. It records the responses a test needs on the first run, writes them to disk, and replays them from disk on every run after that.</p><div class="danger custom-block"><p class="custom-block-title">🛑 CANARY ONLY 🛑</p><p>Holodeck is still experimental and publishes to the <code>canary</code> channel only. Install it with an exact version, as <a href="./server-setup">Server setup</a> shows.</p></div><h2 id="holodeck-runs-a-real-server" tabindex="-1">Holodeck runs a real server <a class="header-anchor" href="#holodeck-runs-a-real-server" aria-label="Permalink to “Holodeck runs a real server”">​</a></h2><p>Most browser mocking libraries answer <code>fetch</code> inside the page. Mirage, MSW, and Pretender all work that way. Holodeck does not. It runs a Hono server over TLS and HTTP/2 on its own port, in a worker thread next to your test server, and your tests make real cross-origin requests to it.</p><p>That choice buys you three things a page-level interceptor cannot give you.</p><ul><li>Every request appears in the DevTools network panel, with its real status, headers, and timing.</li><li>Responses are really brotli-compressed and really served over HTTP/2, so compression and streaming behave the way they do in production.</li><li>A request that aborts, redirects, or fails does so in the browser&#39;s own networking stack rather than in a stub.</li></ul><p>It also costs you two things, and both are setup rather than test code. The server needs a locally trusted TLS certificate, and it needs a port of its own. <a href="./server-setup">Server setup</a> covers both.</p><p>Running the mock inside <strong><em>Warp</em>Drive</strong> rather than beside it is the other half of the argument. <strong><em>Warp</em>Drive</strong> already knows your schemas and your request builders, so a mock library that shares them can scope every request to a test, skip work in replay, and keep using the same builders your application code uses.</p><div class="tip custom-block"><p class="custom-block-title">More is planned</p><p><a href="https://github.com/warp-drive-data/warp-drive/pull/11205" target="_blank" rel="noreferrer">Read the proposal</a> for more advanced features, such as reusable mock scenarios and recording against a real API.</p></div><h2 id="record-once-replay-forever" tabindex="-1">Record once, replay forever <a class="header-anchor" href="#record-once-replay-forever" aria-label="Permalink to “Record once, replay forever”">​</a></h2><p>A holodeck test declares what the server should say, then makes the request it would make in production.</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { GET } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/holodeck/mock&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { buildBaseURL } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/utilities&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;users/1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  data: { id: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, type: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, attributes: { name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Chris Thoburn&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}));</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> store.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ url: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">buildBaseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ resourcePath: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;users/1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) });</span></span></code></pre></div><p>What that <code>GET</code> call does depends on which mode the build is in.</p><p>In <strong>record</strong> mode it runs your response function, posts the result to the mock server, and the server writes two files under <code>.mock-cache/</code>. One holds the response metadata as JSON. The other holds the response body, brotli-compressed.</p><p>In <strong>replay</strong> mode it returns immediately. Your response function never runs. The request that follows is served from the files on disk.</p><p>Recording is the default when you run tests locally. Replay is the default in CI. Nothing in the test changes between the two.</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>record run                          replay run</span></span>
<span class="line"><span>  GET(this, &#39;users/1&#39;, fn)            GET(this, &#39;users/1&#39;, fn)</span></span>
<span class="line"><span>    fn() runs                           returns immediately, fn() never runs</span></span>
<span class="line"><span>    POST /__record                      no request</span></span>
<span class="line"><span>    server writes .mock-cache/…         nothing written</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  store.request(…)                    store.request(…)</span></span>
<span class="line"><span>    GET /users/1?__xTestId=…            GET /users/1?__xTestId=…</span></span>
<span class="line"><span>    server writes nothing               server reads .mock-cache/…</span></span>
<span class="line"><span>    responds from the scaffold          responds from disk</span></span></code></pre></div><p>Skipping the work is the point. A suite of two hundred replayed tests builds no payloads and constructs no fixtures. You paid that cost once, when you wrote the test.</p><h2 id="fixtures-are-source-code" tabindex="-1">Fixtures are source code <a class="header-anchor" href="#fixtures-are-source-code" aria-label="Permalink to “Fixtures are source code”">​</a></h2><p>The <code>.mock-cache</code> directory belongs in version control. It is not build output, and nothing regenerates it in CI.</p><p>Committing them is what makes the cache work. Git manages it, so switching branches switches the fixtures with the tests they belong to, and a rebase or a CI run skips recording entirely because the files are already there.</p><p>This catches people out because a local run always passes. Recording is on locally, so a test with no committed fixture records one and goes green. The same test fails in CI, where replay is enforced and the file is missing.</p><p><a href="./record-and-replay">Recording and replaying</a> covers the workflow that avoids this, including the one command that reproduces CI&#39;s behavior before you push.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to “Where to go next”">​</a></h2><ul><li><a href="./server-setup">Server setup</a> installs the package, the certificate, and the server.</li><li><a href="./client-setup">Client setup</a> puts the handler in your request chain.</li><li><a href="./test-framework-integration">Test framework integration</a> wires the test id and the host.</li><li><a href="./common-setups/">Common setups</a> puts the mock server on the test page&#39;s own origin, from Vite, from testem, or behind Caddy.</li><li><a href="./writing-mocks">Writing mocks</a> covers the mock helpers and the rules for matching a request.</li><li><a href="./record-and-replay">Recording and replaying</a> covers the modes, the fixtures, and CI.</li><li><a href="./troubleshooting">Troubleshooting</a> is indexed by the error text you see.</li></ul>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};